// Completion handling
func handleComplete(args []string) {
	// args are the words to complete, last is current word
	// Cobra's __complete prints completions to stdout and directive to stderr via "Completion ended with directive: ..."
	// We need to mimic behavior for cases.

	// If no args, print ":0"
	if len(args) == 0 {
		fmt.Println(":0")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
		return
	}

	// Determine cur and prev
	// In cobra, args include all words including current incomplete word.
	// For example: __complete --  => args = ["--"]
	// __complete "" => args = [""]
	// __complete --config "" => args = ["--config", ""]
	// So cur = last arg, prev = second last if exists

	cur := args[len(args)-1]
	prev := ""
	if len(args) >= 2 {
		prev = args[len(args)-2]
	}

	// Special handling for --config and --completion
	if prev == "--config" {
		// return yaml file ext completion
		fmt.Println("yaml")
		fmt.Println(":8")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveFilterFileExt")
		return
	}
	if prev == "--completion" || strings.HasPrefix(prev, "--completion=") {
		// list shells
		fmt.Println("bash")
		fmt.Println("zsh")
		fmt.Println("fish")
		fmt.Println("powershell")
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return
	}
	if strings.HasPrefix(cur, "--completion=") {
		// after =?
		// For __complete --completion=  ? not needed
	}

	// If cur starts with "--" or "-"
	if strings.HasPrefix(cur, "--") {
		// If cur == "--", list all long flags
		// If cur == "--help", list matching flags starting with that prefix
		// For simplicity, list all long flags that have prefix cur (if cur is "--", all)
		// Use compLong list

		// compLong contains lines like "--align\tdesc"
		// We'll parse our embedded compLong
		lines := strings.Split(strings.TrimSpace(compLong), "\n")
		// Filter
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			if strings.HasPrefix(line, ":") {
				continue
			}
			// flag is before tab
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		// If cur is exactly a flag that expects arg? Like "--config" without value, then it should list that flag itself? In observed, __complete --filter returned "--filter\t..."
		// Our filtering will handle

		// If no match and cur == "--", we already have all
		if cur == "--" {
			// output all long flags (compLong already)
			// But compLong file includes all long flags without directive line
			// We need to output them and then :4
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				if strings.HasPrefix(line, ":") {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		// For other prefixes, output matched
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		// If no match, maybe it's completing value for a flag? Fall back to default
	}

	if strings.HasPrefix(cur, "-") && !strings.HasPrefix(cur, "--") {
		// Could be "-" or "-x" etc
		if cur == "-" {
			// list all flags (short and long)
			lines := strings.Split(strings.TrimSpace(compAll), "\n")
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				if strings.HasPrefix(line, ":") {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		// For "-", we already handled
		// For other short prefixes like "-x", we should list matching short and long?
		// Simplify: if cur starts with "-", list all matching from compAll
		lines := strings.Split(strings.TrimSpace(compAll), "\n")
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			if strings.HasPrefix(line, ":") {
				continue
			}
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}

	// For empty cur or other cases, return default file completion
	// Cases like __complete "" or __complete --filter "" should return :0
	// Also __complete --config "" handled earlier as yaml, but for other flags return :0

	// Special case: if cur == "" and prev is flag that needs arg with no special completion, return :0

	fmt.Println(":0")
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
}
