		{long: "view-mode", short: 'm', needsArg: true},
		{long: "watch", short: 'T', needsArg: true},
		{long: "wrap", short: 'w', isBool: true},
	}

	longMap := make(map[string]flagDef)
	shortMap := make(map[byte]flagDef)
	for _, d := range defs {
		longMap[d.long] = d
		if d.short != 0 {
			shortMap[d.short] = d
		}
	}

	var (
		configPath       string
		completionArg    string
		hasCompletion    bool
		hasHelp          bool
		hasVersion       bool
		hasHelpKey       bool
		hasListViewModes bool
		hasForceScreen   bool
		forceScreenVal   bool
	)

	var fileArgs []string
	var configError string

	i := 0
	for i < len(args) {
