		}
		if strings.HasPrefix(arg, "--") {
			nameVal := arg[2:]
			var name, val string
			var hasEq bool
			if idx := strings.Index(nameVal, "="); idx != -1 {
				name = nameVal[:idx]
				val = nameVal[idx+1:]
				hasEq = true
			} else {
				name = nameVal
			}
			fd, ok := longMap[name]
			if !ok {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: --%s\n", name)
				os.Exit(1)
			}
			if fd.isBool {
				if hasEq && val != "" {
					if _, err := strconv.ParseBool(val); err != nil {
						shortPart := ""
						if fd.short != 0 {
							shortPart = fmt.Sprintf("-%c, ", fd.short)
