						os.Exit(1)
					}
					if name == "force-screen" {
						hasForceScreen = true
						b, _ := strconv.ParseBool(val)
						forceScreenVal = b
					}
				} else {
					if name == "force-screen" {
						hasForceScreen = true
						forceScreenVal = true
					}
				}
				switch name {
				case "help":
					hasHelp = true
				case "version":
					hasVersion = true
				case "help-key":
					hasHelpKey = true
				case "list-view-modes":
					hasListViewModes = true
				}
				i++
				continue
			} else {
				var argVal string
				if hasEq {
					argVal = val
				} else {
					if i+1 >= len(args) {
						fmt.Fprintf(os.Stderr, "Error: flag needs an argument: --%s\n", name)
						os.Exit(1)
					}
					argVal = args[i+1]
					i++
				}
				switch name {
				case "header", "header-column", "exit-write-after", "exit-write-before", "memory-limit", "memory-limit-file", "notify-eof", "ruler", "section-header-num", "section-start", "skip-lines", "tab-width", "vertical-header":
					if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
						shortPart := ""
						if fd.short != 0 {
							shortPart = fmt.Sprintf("-%c, ", fd.short)
						}
						fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"%s--%s\" flag: %s\n", argVal, shortPart, fd.long, err)
						os.Exit(1)
					}
				case "watch":
					if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
						shortPart := ""
						if fd.short != 0 {
							shortPart = fmt.Sprintf("-%c, ", fd.short)
						}
						fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"%s--%s\" flag: %s\n", argVal, shortPart, fd.long, err)
						os.Exit(1)
					}
				}
				switch name {
				case "config":
					configPath = argVal
				case "completion":
					hasCompletion = true
					completionArg = argVal
				}
				i++
				continue
			}
		} else if strings.HasPrefix(arg, "-") && arg != "-" {
			token := arg[1:]
			j := 0
			consumedNext := false
			for j < len(token) {
				ch := token[j]
				fd, ok := shortMap[ch]
				if !ok {
					fmt.Fprintf(os.Stderr, "Error: unknown shorthand flag: '%c' in -%s\n", ch, token)
					os.Exit(1)
				}
				if fd.isBool {
					switch fd.long {
					case "help":
						hasHelp = true
					case "version":
						hasVersion = true
					case "force-screen":
						// Note: short for force-screen? No short, but keep
						hasForceScreen = true
						forceScreenVal = true
					}
					j++
					continue
				} else {
					var argVal string
					if j+1 < len(token) {
						argVal = token[j+1:]
						j = len(token)
					} else {
						if i+1 >= len(args) {
							fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '%c' in -%s\n", ch, token)
							os.Exit(1)
						}
						argVal = args[i+1]
						consumedNext = true
					}
					switch fd.long {
					case "header", "header-column", "exit-write-after", "exit-write-before", "memory-limit", "memory-limit-file", "notify-eof", "ruler", "section-header-num", "section-start", "skip-lines", "tab-width", "vertical-header":
						if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
							fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"-%c, --%s\" flag: %s\n", argVal, ch, fd.long, err)
							os.Exit(1)
						}
					case "watch":
						if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
							fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"-%c, --%s\" flag: %s\n", argVal, ch, fd.long, err)
							os.Exit(1)
						}
					}
					switch fd.long {
					case "config":
						configPath = argVal
					case "completion":
						hasCompletion = true
						completionArg = argVal
					}
					break
				}
			}
			i++
			if consumedNext {
				i++
			}
			continue
		} else {
			fileArgs = append(fileArgs, arg)
			i++
		}
	}

	// Config handling
	var modes []string
	if configPath != "" {
		data, err := os.ReadFile(configPath)
		if err != nil {
			configError = fmt.Sprintf("failed to read config file: %s", err.Error())
		} else {
			var cfg map[string]interface{}
			if err := yaml.Unmarshal(data, &cfg); err != nil {
				configError = fmt.Sprintf("failed to read config file: While parsing config: %s", err.Error())
			} else {
				if modeRaw, ok := cfg["Mode"]; ok {
					switch m := modeRaw.(type) {
					case map[string]interface{}:
						for k := range m {
							modes = append(modes, k)
						}
					case map[interface{}]interface{}:
						for k := range m {
							if ks, ok := k.(string); ok {
								modes = append(modes, ks)
							}
						}
					}
				}
			}
		}
	}

	if hasHelp {
		fmt.Print(helpText)
		return
	}
	if hasVersion {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
