		// Ensure general included; sorting already
		seen := make(map[string]bool)
		uniq := []string{}
		for _, mm := range allModes {
			if !seen[mm] {
				seen[mm] = true
				uniq = append(uniq, mm)
			}
		}
		for _, mm := range uniq {
			fmt.Println(mm)
		}
