			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}
	fmt.Println(":0")
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
}

