				case "header", "header-column", "exit-write-after", "exit-write-before", "memory-limit", "memory-limit-file", "notify-eof", "ruler", "section-header-num", "section-start", "skip-lines", "tab-width", "vertical-header":
					if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
						shortPart := ""
						if fd.short != 0 {
							shortPart = fmt.Sprintf("-%c, ", fd.short)
						}
						fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"%s--%s\" flag: %s\n", argVal, shortPart, fd.long, err)
						os.Exit(1)
					}
				case "watch":
					if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
						shortPart := ""
						if fd.short != 0 {
							shortPart = fmt.Sprintf("-%c, ", fd.short)
						}
						fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"%s--%s\" flag: %s\n", argVal, shortPart, fd.long, err)
						os.Exit(1)
					}
				}
				switch name {
				case "config":
					configPath = argVal
				case "completion":
					hasCompletion = true
					completionArg = argVal
				}
				i++
				continue
			}
		} else if strings.HasPrefix(arg, "-") && arg != "-" {
			token := arg[1:]
			j := 0
			consumedNext := false
			for j < len(token) {
				ch := token[j]
				fd, ok := shortMap[ch]
				if !ok {
					fmt.Fprintf(os.Stderr, "Error: unknown shorthand flag: '%c' in -%s\n", ch, token)
					os.Exit(1)
				}
				if fd.isBool {
					switch fd.long {
					case "help":
						hasHelp = true
					case "version":
						hasVersion = true
					}
					j++
					continue
				} else {
					var argVal string
					if j+1 < len(token) {
						argVal = token[j+1:]
						j = len(token)
					} else {
						if i+1 >= len(args) {
							fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '%c' in -%s\n", ch, token)
							os.Exit(1)
						}
						argVal = args[i+1]
						consumedNext = true
					}
					switch fd.long {
					case "header", "header-column", "exit-write-after", "exit-write-before", "memory-limit", "memory-limit-file", "notify-eof", "ruler", "section-header-num", "section-start", "skip-lines", "tab-width", "vertical-header":
						if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
							fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"-%c, --%s\" flag: %s\n", argVal, ch, fd.long, err)
							os.Exit(1)
						}
					case "watch":
						if _, err := strconv.ParseInt(argVal, 10, 64); err != nil {
							fmt.Fprintf(os.Stderr, "Error: invalid argument %q for \"-%c, --%s\" flag: %s\n", argVal, ch, fd.long, err)
							os.Exit(1)
						}
					}
					switch fd.long {
					case "config":
						configPath = argVal
					}
					break
				}
			}
			i++
			if consumedNext {
				i++
			}
			continue
		} else {
			fileArgs = append(fileArgs, arg)
			i++
		}
	}

	var modes []string
	if configPath != "" {
		data, err := os.ReadFile(configPath)
		if err != nil {
			configError = fmt.Sprintf("failed to read config file: %s", err.Error())
		} else {
			var cfg map[string]interface{}
			if err := yaml.Unmarshal(data, &cfg); err != nil {
				configError = fmt.Sprintf("failed to read config file: While parsing config: %s", err.Error())
			} else {
				if modeRaw, ok := cfg["Mode"]; ok {
					switch m := modeRaw.(type) {
					case map[string]interface{}:
						for k := range m {
							modes = append(modes, k)
						}
					case map[interface{}]interface{}:
						for k := range m {
							if ks, ok := k.(string); ok {
								modes = append(modes, ks)
							}
						}
					}
				}
			}
		}
	}

	if hasHelp {
		fmt.Print(helpText)
		return
	}
	if hasVersion {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fmt.Print("ov version dev rev:HEAD\n")
		return
	}
	if hasHelpKey {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fmt.Print(helpKeyText)
		return
	}
	if hasListViewModes {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		allModes := []string{"general"}
		allModes = append(allModes, modes...)
		sort.Strings(allModes)
		seen := make(map[string]bool)
		uniq := []string{}
		for _, mm := range allModes {
			if !seen[mm] {
				seen[mm] = true
				uniq = append(uniq, mm)
			}
		}
		for _, mm := range uniq {
			fmt.Println(mm)
		}
		return
	}
	if hasCompletion {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		switch completionArg {
		case "bash":
			fmt.Print(compBash)
		case "zsh":
			fmt.Print(compZsh)
		case "fish":
			fmt.Print(compFish)
		case "powershell":
			fmt.Print(compPowershell)
		default:
			fmt.Fprintln(os.Stderr, "Error: requires one of the arguments bash/zsh/fish/powershell")
			os.Exit(1)
		}
		return
	}

	isStdinTTY := isatty.IsTerminal(os.Stdin.Fd()) || isatty.IsCygwinTerminal(os.Stdin.Fd())
	isStdoutTTY := isatty.IsTerminal(os.Stdout.Fd()) || isatty.IsCygwinTerminal(os.Stdout.Fd())

	effectiveForceScreen := hasForceScreen && forceScreenVal

	if len(fileArgs) == 0 {
		if !isStdinTTY {
			if effectiveForceScreen {
				fmt.Fprintln(os.Stderr, "Error: missing file")
				os.Exit(1)
			}
			if configError != "" {
				fmt.Fprintln(os.Stderr, configError)
			}
			_, _ = io.Copy(os.Stdout, os.Stdin)
			return
		} else {
			if effectiveForceScreen {
				fmt.Fprintln(os.Stderr, "Error: missing file")
				os.Exit(1)
			}
			if configError != "" {
				fmt.Fprintln(os.Stderr, configError)
			}
			return
		}
	}

	if effectiveForceScreen {
		fname := fileArgs[0]
		info, err := os.Stat(fname)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: '%s' not found\n", fname)
			os.Exit(1)
		}
		if info.IsDir() {
			fmt.Fprintf(os.Stderr, "Error: '%s' is a directory\n", fname)
			os.Exit(1)
		}
		tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			if isStdinTTY {
				for _, fa := range fileArgs {
					data, _ := os.ReadFile(fa)
					os.Stdout.Write(data)
				}
			}
			fmt.Fprintln(os.Stderr, "Error: Screen.Init(): open /dev/tty: no such device or address")
			os.Exit(1)
		}
		tty.Close()
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		runPager(fileArgs[0])
		return
	}

	if !isStdoutTTY {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fname := fileArgs[0]
		f, err := os.Open(fname)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: open %s: no such file or directory\n", fname)
			os.Exit(1)
		}
		defer f.Close()
		info, _ := f.Stat()
		if info.IsDir() {
			fmt.Fprintln(os.Stderr, "Error: write /dev/stdout: copy_file_range: is a directory")
			os.Exit(1)
		}
		_, _ = io.Copy(os.Stdout, f)
		return
	}

	if configError != "" {
		fmt.Fprintln(os.Stderr, configError)
	}
	runPager(fileArgs[0])
}

func runPager(fname string) {
	info, err := os.Stat(fname)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: '%s' not found\n", fname)
		os.Exit(1)
	}
	if info.IsDir() {
		fmt.Fprintf(os.Stderr, "Error: '%s' is a directory\n", fname)
		os.Exit(1)
	}
	content := readFileMaybeDecompress(fname)
	ttyIn, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Print(string(content))
		return
	}
	defer ttyIn.Close()
	fmt.Print("\033[2J\033[H")
	fmt.Print(string(content))
	fmt.Printf("\n%s: (1/1)\n", fname)
	reader := bufio.NewReader(ttyIn)
	for {
		r, _, err := reader.ReadRune()
		if err != nil {
			break
		}
		if r == 'q' || r == 'Q' || r == 27 {
			break
		}
	}
	fmt.Print("\033[2J\033[H")
}

func readFileMaybeDecompress(path string) []byte {
	data, err := os.ReadFile(path)
	if err != nil {
		return []byte{}
	}
	lower := strings.ToLower(path)
	if strings.HasSuffix(lower, ".gz") || (len(data) >= 3 && data[0] == 0x1F && data[1] == 0x8B) {
		if dec, err := decompressGzip(data); err == nil {
			return dec
		}
	}
	if bytes.HasPrefix(data, []byte("BZ")) {
		if dec, err := decompressBzip2(data); err == nil {
			return dec
		}
	}
	return data
}

func decompressGzip(data []byte) ([]byte, error) {
	r, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}

func decompressBzip2(data []byte) ([]byte, error) {
	r := bzip2.NewReader(bytes.NewReader(data))
	return io.ReadAll(r)
}

func handleComplete(args []string) {
	if len(args) == 0 {
		fmt.Println(":0")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
		return
	}
	cur := args[len(args)-1]
	prev := ""
	if len(args) >= 2 {
		prev = args[len(args)-2]
	}
	if prev == "--config" {
		fmt.Println("yaml")
		fmt.Println(":8")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveFilterFileExt")
		return
	}
	if prev == "--completion" || strings.HasPrefix(prev, "--completion=") {
		fmt.Println("bash")
		fmt.Println("zsh")
		fmt.Println("fish")
		fmt.Println("powershell")
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return
	}
	if strings.HasPrefix(cur, "--") {
		lines := strings.Split(strings.TrimSpace(compLong), "\n")
		if cur == "--" {
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}
	if strings.HasPrefix(cur, "-") && !strings.HasPrefix(cur, "--") {
		if cur == "-" {
			lines := strings.Split(strings.TrimSpace(compAll), "\n")
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		lines := strings.Split(strings.TrimSpace(compAll), "\n")
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}
	fmt.Println(":0")
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
}

