	}

	var modes []string
	if configPath != "" {
		data, err := os.ReadFile(configPath)
		if err != nil {
			configError = fmt.Sprintf("failed to read config file: %s", err.Error())
		} else {
			parsedModes, parseErr := parseModesFromYAML(string(data))
			if parseErr != "" {
				configError = fmt.Sprintf("failed to read config file: While parsing config: %s", parseErr)
			} else {
				modes = parsedModes
			}
		}
	}

	if hasHelp {
		fmt.Print(helpText)
		return
	}
	if hasVersion {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fmt.Print("ov version dev rev:HEAD\n")
		return
	}
	if hasHelpKey {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fmt.Print(helpKeyText)
		return
	}
	if hasListViewModes {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		allModes := []string{"general"}
		allModes = append(allModes, modes...)
		sort.Strings(allModes)
		seen := make(map[string]bool)
		uniq := []string{}
		for _, mm := range allModes {
			if !seen[mm] {
				seen[mm] = true
				uniq = append(uniq, mm)
			}
		}
		for _, mm := range uniq {
			fmt.Println(mm)
		}
		return
	}
	if hasCompletion {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		switch completionArg {
		case "bash":
			fmt.Print(compBash)
		case "zsh":
			fmt.Print(compZsh)
		case "fish":
			fmt.Print(compFish)
		case "powershell":
			fmt.Print(compPowershell)
		default:
			fmt.Fprintln(os.Stderr, "Error: requires one of the arguments bash/zsh/fish/powershell")
			os.Exit(1)
		}
		return
	}

	isStdinTTY := isTerminal(os.Stdin)
	isStdoutTTY := isTerminal(os.Stdout)

	effectiveForceScreen := hasForceScreen && forceScreenVal

	if len(fileArgs) == 0 {
		if !isStdinTTY {
			if effectiveForceScreen {
				fmt.Fprintln(os.Stderr, "Error: missing file")
				os.Exit(1)
			}
			if configError != "" {
				fmt.Fprintln(os.Stderr, configError)
			}
			_, _ = io.Copy(os.Stdout, os.Stdin)
			return
		} else {
			if effectiveForceScreen {
				fmt.Fprintln(os.Stderr, "Error: missing file")
				os.Exit(1)
			}
			if configError != "" {
				fmt.Fprintln(os.Stderr, configError)
			}
			return
		}
	}

	if effectiveForceScreen {
		fname := fileArgs[0]
		info, err := os.Stat(fname)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: '%s' not found\n", fname)
			os.Exit(1)
		}
		if info.IsDir() {
			fmt.Fprintf(os.Stderr, "Error: '%s' is a directory\n", fname)
			os.Exit(1)
		}
		tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			if isStdinTTY {
				for _, fa := range fileArgs {
					data, _ := os.ReadFile(fa)
					os.Stdout.Write(data)
				}
			}
			fmt.Fprintln(os.Stderr, "Error: Screen.Init(): open /dev/tty: no such device or address")
			os.Exit(1)
		}
		tty.Close()
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		runPager(fileArgs[0])
		return
	}

	if !isStdoutTTY {
		if configError != "" {
			fmt.Fprintln(os.Stderr, configError)
		}
		fname := fileArgs[0]
		f, err := os.Open(fname)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: open %s: no such file or directory\n", fname)
			os.Exit(1)
		}
		defer f.Close()
		info, _ := f.Stat()
		if info.IsDir() {
			fmt.Fprintln(os.Stderr, "Error: write /dev/stdout: copy_file_range: is a directory")
			os.Exit(1)
		}
		_, _ = io.Copy(os.Stdout, f)
		return
	}

	if configError != "" {
		fmt.Fprintln(os.Stderr, configError)
	}
	runPager(fileArgs[0])
}

func parseModesFromYAML(content string) ([]string, string) {
	trimmed := strings.TrimSpace(content)
	if strings.Contains(trimmed, "[") && !strings.Contains(trimmed, "]") {
		return nil, "yaml: line 1: did not find expected ',' or ']'"
	}
	var modes []string
	lines := strings.Split(content, "\n")
	inMode := false
	modeIndent := -1
	for _, line := range lines {
		t := strings.TrimSpace(line)
		if t == "" || strings.HasPrefix(t, "#") {
			continue
		}
		indent := len(line) - len(strings.TrimLeft(line, " "))
		if !inMode {
			if strings.HasPrefix(t, "Mode:") {
				inMode = true
				modeIndent = indent
				continue
			}
		} else {
			if indent <= modeIndent {
				// exit mode
				inMode = false
				// check if this line is new Mode?
				if strings.HasPrefix(t, "Mode:") {
					inMode = true
					modeIndent = indent
				}
				continue
			}
			// Only keys at exactly modeIndent+2
			if indent == modeIndent+2 {
				// Extract key before :
				if idx := strings.Index(t, ":"); idx != -1 {
					key := strings.TrimSpace(t[:idx])
					if key != "" {
						modes = append(modes, key)
					}
				}
			}
		}
	}
	return modes, ""
}

func runPager(fname string) {
	info, err := os.Stat(fname)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: '%s' not found\n", fname)
		os.Exit(1)
	}
	if info.IsDir() {
		fmt.Fprintf(os.Stderr, "Error: '%s' is a directory\n", fname)
		os.Exit(1)
	}
	content := readFileMaybeDecompress(fname)
	ttyIn, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Print(string(content))
		return
	}
	defer ttyIn.Close()
	fmt.Print("\033[2J\033[H")
	fmt.Print(string(content))
	fmt.Printf("\n%s: (1/1)\n", fname)
	reader := bufio.NewReader(ttyIn)
	for {
		r, _, err := reader.ReadRune()
		if err != nil {
			break
		}
		if r == 'q' || r == 'Q' || r == 27 {
			break
		}
	}
	fmt.Print("\033[2J\033[H")
}

func readFileMaybeDecompress(path string) []byte {
	data, err := os.ReadFile(path)
	if err != nil {
		return []byte{}
	}
	lower := strings.ToLower(path)
	if strings.HasSuffix(lower, ".gz") || (len(data) >= 3 && data[0] == 0x1F && data[1] == 0x8B) {
		if dec, err := decompressGzip(data); err == nil {
			return dec
		}
	}
	if bytes.HasPrefix(data, []byte("BZh")) {
		if dec, err := decompressBzip2(data); err == nil {
			return dec
		}
	}
	return data
}

func decompressGzip(data []byte) ([]byte, error) {
	r, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}

func decompressBzip2(data []byte) ([]byte, error) {
	r := bzip2.NewReader(bytes.NewReader(data))
	return io.ReadAll(r)
}

func handleComplete(args []string) {
	if len(args) == 0 {
		fmt.Println(":0")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
		return
	}
	cur := args[len(args)-1]
	prev := ""
	if len(args) >= 2 {
		prev = args[len(args)-2]
	}
	if prev == "--config" {
		fmt.Println("yaml")
		fmt.Println(":8")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveFilterFileExt")
		return
	}
	if prev == "--completion" || strings.HasPrefix(prev, "--completion=") {
		fmt.Println("bash")
		fmt.Println("zsh")
		fmt.Println("fish")
		fmt.Println("powershell")
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return
	}
	if strings.HasPrefix(cur, "--") {
		lines := strings.Split(strings.TrimSpace(compLong), "\n")
		if cur == "--" {
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}
	if strings.HasPrefix(cur, "-") && !strings.HasPrefix(cur, "--") {
		if cur == "-" {
			lines := strings.Split(strings.TrimSpace(compAll), "\n")
			for _, line := range lines {
				if strings.TrimSpace(line) == "" {
					continue
				}
				fmt.Println(line)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
		lines := strings.Split(strings.TrimSpace(compAll), "\n")
		var matched []string
		for _, line := range lines {
			if strings.TrimSpace(line) == "" {
				continue
			}
			parts := strings.SplitN(line, "\t", 2)
			flag := parts[0]
			if strings.HasPrefix(flag, cur) {
				matched = append(matched, line)
			}
		}
		if len(matched) > 0 {
			for _, m := range matched {
				fmt.Println(m)
			}
			fmt.Println(":4")
			fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
			return
		}
	}
	fmt.Println(":0")
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
}

